'use client';
import {useCallback,useEffect,useMemo,useRef,useState} from 'react';
import {Waves,LayoutDashboard,Map,ChartNoAxesCombined,RadioTower,Bell,MapPin,Package,ShoppingCart,Wrench,BookOpen,GraduationCap,ShieldCheck,Users,ScrollText,Workflow,Search,ChevronRight,ChevronDown,ArrowUpRight,ArrowRight,RefreshCw,Download,Plus,Settings2,SlidersHorizontal,Check,CheckCircle2,Clock,TriangleAlert,Wifi,WifiOff,Battery,Activity,Building2,Menu,X,Printer,Send,FileText,CheckCheck,Pause,Play,LoaderCircle,Eye,Shield,ExternalLink,ArrowDown,CalendarDays,Copy,Mountain,Navigation,ClipboardList} from 'lucide-react';
import type {Bootstrap,Station,Reading,Role,Session} from '../../lib/types';
import {roleLabels,statusLabels} from '../../lib/seed';
import RiverMap from './RiverMap';
import {ReadingChart,Spark} from './Charts';
import {Badge,Empty,Loading,SectionHead,Modal,Field,Fact,dateTime,timeOnly,num,downloadBlob,Details} from './ui';
import Equipment from './Equipment';
import Knowledge from './Knowledge';
import Measurements from './Measurements';
import {StationProfile,StationProfileSummary,RiverSectionFields} from './StationProfile';

type Page='overview'|'map'|'measurements'|'stations'|'alerts'|'pilot'|'equipment'|'orders'|'service'|'documents'|'training'|'compliance'|'quality'|'automation'|'users'|'audit';
type FormState={type:string;id?:string;productId?:string;stationId?:string;snapshot?:Station};
const navigation=[{label:'НАБЛЮДЕНИЕ',items:[['overview','Преглед',LayoutDashboard],['map','Карта на станциите',Map],['measurements','Измервания',ChartNoAxesCombined],['stations','Станции',RadioTower],['alerts','Сигнали',Bell]]},{label:'УПРАВЛЕНИЕ',items:[['pilot','Пилот · Трявна',MapPin],['equipment','Оборудване',Package],['orders','Заявки за доставка',ShoppingCart],['service','Сервиз и поддръжка',Wrench]]},{label:'РЕСУРСИ',items:[['documents','Документи и формуляри',BookOpen],['training','Обучения',GraduationCap],['compliance','Правила и стандарти',ShieldCheck],['quality','Изисквания и качество',ClipboardList]]},{label:'СИСТЕМА',items:[['automation','Автоматизации',Workflow],['users','Достъп и роли',Users],['audit','Журнал на действията',ScrollText]]}] as const;
function pageName(p:Page){for(const g of navigation)for(const item of g.items)if(item[0]===p)return item[1];return 'Преглед'}
const productNames:Record<string,string>={rls500:'OTT RLS 500 · радарен нивомер',pls500:'OTT PLS 500 · датчик за налягане',pluvio:'OTT Pluvio² S · дъждомер',rq30:'SOMMER RQ-30+ · скорост / разход',exo2:'YSI EXO2 · качество на водата',netdl:'Регистратор и телеметрия',solar:'Автономно соларно захранване',gauge:'Водомерна рейка',cabinet:'Шкаф и монтажен комплект'};
const canManage=(s:Session,municipality:string)=>s.role==='admin'||s.role==='municipal'&&s.municipality===municipality;
const canService=(s:Session,municipality:string)=>canManage(s,municipality)||s.role==='technician'&&s.municipality===municipality;
const permissions=[['Преглед на карта и измервания','Всички','Всички','Всички','Всички','Всички'],['Настройки на станции','Всички','Собствена община','—','—','—'],['Съгласуване на места','Одобрява','Подаване за общината','—','—','—'],['Експорт на измервания','Всички','Собствена община','Всички','—','—'],['Заявки за оборудване','Всички','Собствена община','—','—','—'],['Сервизни заявки','Всички','Собствена община','—','Собствена община','—'],['Роли и автоматизации','Всички','—','—','—','—']];
async function api<T=Record<string,unknown>>(path:string,init?:RequestInit):Promise<T>{const res=await fetch('/api/'+path,{...init,headers:{'Content-Type':'application/json',...init?.headers}});if(!res.ok){let data:{error?:string}|undefined;try{data=await res.json() as {error?:string}}catch{}throw new Error(data?.error||`Заявката не е изпълнена (${res.status}).`)}return res.json() as Promise<T>}
const json=(data:unknown,method='POST')=>({method,body:JSON.stringify(data)});

export default function RiverApp(){
 const [profileId,setProfileId]=useState<string|null>(null);
 const [page,setPage]=useState<Page>('overview');const [data,setData]=useState<Bootstrap|null>(null);const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [auto,setAuto]=useState(true);const [countdown,setCountdown]=useState(30);const [selected,setSelected]=useState('TRV-002');const [history,setHistory]=useState<Reading[]>([]);const [toast,setToast]=useState('');const [form,setForm]=useState<FormState|null>(null);const [formError,setFormError]=useState('');const [mobile,setMobile]=useState(false);const [search,setSearch]=useState('');const [scope,setScope]=useState('');const [mapStatus,setMapStatus]=useState('');const [focus,setFocus]=useState<{lat:number;lng:number;zoom:number;key:number}>();const [alertTab,setAlertTab]=useState('open');const [stationQuery,setStationQuery]=useState('');const [auditQuery,setAuditQuery]=useState('');const toastTimer=useRef<ReturnType<typeof setTimeout>|undefined>(undefined);const formRef=useRef<HTMLFormElement>(null);
 const notify=useCallback((msg:string)=>{setToast(msg);if(toastTimer.current)clearTimeout(toastTimer.current);toastTimer.current=setTimeout(()=>setToast(''),5500)},[]);
 const refresh=useCallback(async(silent=false)=>{if(!silent)setBusy(true);try{const d=await api<Bootstrap>('bootstrap');setData(d);setError('');setCountdown(30)}catch(e){setError((e as Error).message)}finally{if(!silent)setBusy(false)}},[]);
 useEffect(()=>{refresh();const read=()=>{const key=window.location.hash.replace('#','') as Page;if(navigation.some(g=>g.items.some(i=>i[0]===key)))setPage(key)};read();window.addEventListener('hashchange',read);return()=>window.removeEventListener('hashchange',read)},[refresh]);
 useEffect(()=>{if(!auto)return;const id=setInterval(()=>{if(document.hidden)return;setCountdown(c=>{if(c<=1){refresh(true);return 30}return c-1})},1000);return()=>clearInterval(id)},[auto,refresh]);
 useEffect(()=>{if(!data)return;let cancelled=false;const from=new Date(Date.now()-6*3600000).toISOString();api<{readings:Reading[]}>(`measurements?station=${selected}&from=${encodeURIComponent(from)}&to=${encodeURIComponent(new Date().toISOString())}`).then(d=>{if(!cancelled)setHistory((d.readings||[]).sort((a:Reading,b:Reading)=>Date.parse(a.measuredAt)-Date.parse(b.measuredAt)))}).catch(()=>{if(!cancelled)setHistory([])});return()=>{cancelled=true}},[selected,data?.serverTime]);
 const go=(p:Page)=>{setPage(p);window.location.hash=p;setMobile(false);setSearch('');window.scrollTo({top:0,behavior:'smooth'})};
 const openForm=(f:FormState)=>{setFormError('');setForm(f.type==='station'?{...f,snapshot:data?.stations.find(s=>s.id===f.id)}:f)};
 const mutate=async(path:string,body:unknown,method='POST',success='Промяната е запазена.')=>{setBusy(true);try{await api(path,json(body,method));await refresh(true);notify(success);return true}catch(e){notify((e as Error).message);return false}finally{setBusy(false)}};
 const chooseStation=(id:string)=>{setSelected(id);setSearch('')};
 const visibleStations=useMemo(()=>data?.stations.filter(s=>(!scope||s.municipality===scope)&&(!mapStatus||s.current?.status===mapStatus))||[],[data,scope,mapStatus]);
 const station=data?.stations.find(s=>s.id===selected)||data?.stations[0];const openAlerts=data?.alerts.filter(a=>a.status==='open')||[];
 const municipalities=useMemo(()=>[...new Set(data?.stations.map(s=>s.municipality))].sort((a,b)=>a.localeCompare(b,'bg')),[data]);
 const searchResults=data?.stations.filter(s=>(s.name+' '+s.id+' '+s.river).toLowerCase().includes(search.toLowerCase())).slice(0,6)||[];
 const fmt=new Intl.DateTimeFormat('bg-BG',{timeZone:'Europe/Sofia',day:'numeric',month:'long',year:'numeric'});
 async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();if(!form||!data)return;setBusy(true);setFormError('');const fd=new FormData(e.currentTarget),v=Object.fromEntries(fd.entries());try{
  if(form.type==='role'){await api('session',json({role:v.role,municipality:v.role==='municipal'||v.role==='technician'?v.municipality:null}));}
  if(form.type==='order'){await api('orders',json({municipality:v.municipality,productId:v.productId,quantity:Number(v.quantity),reason:v.reason,status:'submitted'}));}
  if(form.type==='station'||form.type==='newstation'){
   const original=form.type==='station'?(form.snapshot||data.stations.find(s=>s.id===form.id)):undefined;
   const settings=Object.fromEntries(Object.entries(v).filter(([key])=>!key.startsWith('section_')));
   const riverSection:Record<string,string>={};
   for(const key of ['name','position','terrain','channel','flowRegime','floodRisks','monitoringFocus','waterBodyCode','typologyCode','sourceTitle','sourceUrl','reference','reviewedBy','reviewedAt','status'] as const){
    const field=fd.get(`section_${key}`);
    if(typeof field==='string'&&field!==(original?.riverSection?.[key]??(key==='position'||key==='terrain'?'unknown':key==='status'?'draft':'')))riverSection[key]=field;
   }
   if(v.section_status==='verified'&&original?.riverSection?.status!=='verified'&&fd.get('section_confirm')!=='yes')throw new Error('За потвърждаване на профила отбележете „Потвърждавам профила след тази редакция“.');
   if(fd.get('section_confirm')==='yes')riverSection.status='verified';
   const body={...settings,version:original?.version,lat:Number(v.lat),lng:Number(v.lng),interval:Number(v.interval),transmitInterval:Number(v.interval),warning:Number(v.warning),critical:Number(v.critical),baseLevel:original?.baseLevel??0.8,battery:original?.battery??100,signal:original?.signal??90,sensors:original?.sensors||['rls500','pls500'],health:v.health||'online',kind:original?.kind||'За експертна оценка',locationStatus:original?.locationStatus||'proposed',...(Object.keys(riverSection).length?{riverSection}:{})};
   await api(form.type==='newstation'?'stations':`stations/${form.id}`,json(body,form.type==='newstation'?'POST':'PATCH'));
  }
  if(form.type==='ticket'){await api('tickets',json({stationId:v.stationId,subject:v.subject,description:v.description,priority:v.priority}));}
  if(form.type==='resolve'){await api(`tickets/${form.id}`,json({status:'resolved',resolution:v.resolution},'PATCH'));}
  if(form.type==='ack'){await api(`alerts/${form.id}/ack`,json({note:v.note}));}
  if(form.type==='approval'){await api('approvals',json({stationId:v.stationId,expert:v.expert,municipalReference:v.municipalReference,regime:v.regime,documentReference:v.documentReference,notes:v.notes,status:'submitted'}));}
  if(form.type==='member'){await api('memberships',json({userId:v.userId,name:v.name,role:v.role,municipality:v.municipality||null}));}
  if(form.type==='handover'){const s=data.stations.find(s=>s.id===v.stationId);const doc=`<!doctype html><html lang="bg"><meta charset="UTF-8"><title>Протокол за предаване на данни</title><style>body{font:15px Arial;max-width:800px;margin:50px auto;line-height:1.7}h1{font-size:24px}table{border-collapse:collapse;width:100%}td{border:1px solid #ccc;padding:10px}.notice{background:#f3f5f4;padding:15px}@media print{button{display:none}}</style><body><h1>RiverGuard · Протокол за предаване на данни</h1><p class="notice">Работен образец · демонстрационни измервания · не е нормативно утвърдена бланка.</p><table><tr><td>Получател / институция</td><td>${escapeHtml(String(v.recipient))}</td></tr><tr><td>Основание</td><td>${escapeHtml(String(v.purpose))}</td></tr><tr><td>Станция</td><td>${escapeHtml(s?.name||'')}</td></tr><tr><td>Подготвил</td><td>${escapeHtml(data.session.name)}</td></tr><tr><td>Дата</td><td>${escapeHtml(dateTime(new Date().toISOString()))} · Europe/Sofia</td></tr><tr><td>Последно ниво</td><td>${num(s?.current?.level)} m · измерено ${dateTime(s?.current?.measuredAt)}</td></tr><tr><td>Предавани файлове</td><td>${escapeHtml(String(v.files))}</td></tr><tr><td>Канал и изходящ №</td><td>__________________________________</td></tr><tr><td>Подпис на предал / приел</td><td>__________________________________</td></tr></table><p>Експортът съдържа данни с обозначен източник и качество. Реалното изпращане се извършва по одобрен от организацията канал и се регистрира с изходящ номер.</p><button onclick="window.print()">Печат</button></body></html>`;downloadBlob(new Blob([doc],{type:'text/html;charset=utf-8'}),'RiverGuard_protokol_predavane.html');}
  await refresh(true);setForm(null);notify(form.type==='handover'?'Протоколът е изтеглен.':'Промяната е записана в демонстрационната среда.');
 }catch(err){setFormError((err as Error).message)}finally{setBusy(false)}}
 if(!data)return <div className="app-loading"><div className="brand loading-brand"><span className="brand-mark"><Waves/></span><strong>RiverGuard</strong></div>{error?<div className="card init-error"><h2>Връзката със системата не е установена</h2><p>{error}</p><button className="button primary" onClick={()=>refresh()}>Опитай отново</button><a className="button secondary" href="/signin-with-chatgpt?return_to=%2F" target="_top">Вход с ChatGPT</a></div>:<><LoaderCircle className="spin"/><p>Подготвяме прегледа на речната мрежа…</p></>}</div>;
 const tryavnaStationCount=data.stations.filter(s=>s.municipality==='Трявна').length;
 const session=data.session;const editableStations=data.stations.filter(s=>canManage(session,s.municipality));const technicalStations=data.stations.filter(s=>canService(session,s.municipality));const activeFormStation=form?.snapshot||data.stations.find(s=>s.id===form?.id);const profileStation=data.stations.find(s=>s.id===profileId);
 const mapView=<div className="card map-card"><div className="card-header"><div className="heading-with-icon"><Map size={18}/><h2>Карта на станциите</h2><span className="count-badge">{visibleStations.length}</span></div><div className="segmented"><button className={!scope?'active':''} onClick={()=>{setScope('');setFocus({lat:42.76,lng:25.36,zoom:7,key:Date.now()})}}>България</button><button className={scope==='Трявна'?'active':''} onClick={()=>{setScope('Трявна');setFocus({lat:42.876,lng:25.493,zoom:13,key:Date.now()});setSelected('TRV-002')}}>Трявна <span className="tiny-tag">пилот</span></button></div></div><RiverMap stations={visibleStations} selected={selected} onSelect={chooseStation} focus={focus} tall={page==='map'}/><div className="map-footer"><span><Navigation size={13}/> Изберете пункт за подробности · плъзнете за преместване</span><span>Позициите са примерни</span></div></div>;
 const stationPanel=station&&<div className="card station-panel">
  <div className="card-header"><span className="eyebrow">ИЗБРАНА СТАНЦИЯ</span><button className="icon-button" title="Настройки на станцията" aria-label="Настройки на избраната станция" onClick={()=>canManage(session,station.municipality)?openForm({type:'station',id:station.id}):go('stations')}><Settings2 size={17}/></button></div>
  <div className="station-body">
   <div className="station-label"><span className="station-code">{station.id}</span><Badge status={station.current?.status}/></div>
   <h2>{station.name}</h2><p className="location-line"><MapPin size={13}/> р. {station.river} · общ. {station.municipality}</p>
   <StationProfileSummary station={station} onOpen={()=>setProfileId(station.id)}/>
   <div className="water-value"><div><span>Радарно ниво</span><strong>{num(station.current?.level,3)} <small>m</small></strong><p>спрямо условната нула на пункта</p></div><div className={`water-emblem ${station.current?.status}`}><Waves size={32}/></div></div>
   <div className="station-facts" style={{marginTop:0,paddingTop:0,borderTop:0}}>
    <Fact label="Контролно · хидростатично" value={num(station.current?.levelBackup,3)} unit="m"/>
    <Fact label="Разлика · контр. − радар" value={num(station.current?.levelDelta,3)} unit="m"/>
   </div>
   {station.current?.levelDelta==null&&<p className="muted" style={{fontSize:10,marginTop:5}}>Разлика се показва при две валидни нива.</p>}
   <div style={{marginTop:10}}>
    <div className="timestamp-row"><span>Оценка на записа</span>{station.current?<Badge status={station.current.quality==='valid'?'normal':station.current.quality==='suspect'?'warning':'offline'}>{{valid:'Валидно',suspect:'За проверка',missing:'Неизползваемо'}[station.current.quality]}</Badge>:<span>Няма данни</span>}</div>
    <div className="timestamp-row"><span>Контролен канал</span>{station.current?<Badge status={station.current.levelBackupQuality==='valid'?'normal':station.current.levelBackupQuality==='suspect'?'warning':'offline'}>{{valid:'Валидно',suspect:'За проверка',missing:'Липсва / неизползваемо'}[station.current.levelBackupQuality]}</Badge>:<span>Няма данни</span>}</div>
   </div>
   <ReadingChart readings={history} threshold={station.warning} compact/>
   <div className="station-facts"><Fact label="Температура" value={num(station.current?.temperature,1)} unit="°C"/><Fact label="Валеж · 1 час" value={num(station.current?.rain,1)} unit="mm"/></div>
   <div className="station-telemetry"><span><Battery size={16}/>{station.current?.battery??station.battery}%</span><span><Wifi size={15}/>{station.current?.signal??station.signal}%</span><span><Clock size={14}/>{station.interval} s</span></div>
   <div className="timestamp-row"><span>Измерено</span><strong>{dateTime(station.current?.measuredAt)}</strong></div><div className="timestamp-row"><span>Получено</span><strong>{dateTime(station.current?.receivedAt)}</strong></div>
   <button className="button secondary full" onClick={()=>go('measurements')}>Всички измервания <ArrowRight size={15}/></button>
  </div>
 </div>;
 return <div className="app-shell"><a className="skip-link" href="#main">Към съдържанието</a>{mobile&&<div className="sidebar-scrim" onClick={()=>setMobile(false)}/>}
 <aside className={`sidebar ${mobile?'open':''}`}><button className="brand" onClick={()=>go('overview')} aria-label="RiverGuard · начало"><span className="brand-mark"><Waves size={24}/></span><span><strong>RiverGuard<span className="brand-period">.</span></strong><small>БЪЛГАРИЯ</small></span></button><div className="workspace-chip"><span className="workspace-symbol"><Building2 size={17}/></span><span>{session.municipality||'Национална мрежа'}<small>{roleLabels[session.role]}</small></span><ChevronDown size={14}/></div><nav>{navigation.map(group=><div className="nav-group" key={group.label}><div className="nav-label">{group.label}</div>{group.items.map(([id,label,Icon])=><button key={id} className={`nav-item ${page===id?'active':''}`} onClick={()=>go(id)} aria-current={page===id?'page':undefined}><Icon size={18}/><span>{label}</span>{id==='alerts'&&openAlerts.length>0&&<span className="nav-count">{openAlerts.length}</span>}{id==='pilot'&&<span className="pilot-dot"/>}</button>)}</div>)}</nav><div className="sidebar-bottom"><div className="environment"><span className="live-dot"/>Демонстрационна среда<span>v1.0</span></div><button className="user-card" onClick={()=>go('users')}><span className="avatar">{session.role==='admin'?'АД':session.role==='municipal'?'ОП':session.role==='analyst'?'АН':session.role==='technician'?'СТ':'НБ'}</span><span><strong>{roleLabels[session.role]}</strong><small>{session.municipality||'RiverGuard България'}</small></span><Settings2 size={17}/></button></div></aside>
 <div className="main-shell"><header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-menu" aria-label="Отвори менюто" onClick={()=>setMobile(true)}><Menu size={20}/></button><span>Работно пространство</span><ChevronRight size={14}/><strong>{pageName(page)}</strong></div><div className="topbar-actions"><div className="global-search"><Search size={16}/><input aria-label="Търси станция или река" placeholder="Търси станция, река…" value={search} onChange={e=>setSearch(e.target.value)}/>{search&&<div className="search-results">{searchResults.length?searchResults.map(s=><button key={s.id} onClick={()=>{chooseStation(s.id);go('map');setScope('');setFocus({lat:s.lat,lng:s.lng,zoom:12,key:Date.now()})}}><MapPin size={16}/><span>{s.name}<small>{s.id} · {s.oblast}</small></span></button>):<p>Няма намерени станции.</p>}</div>}</div><span className="top-divider"/><button className="icon-button notification-bell" title="Сигнали" aria-label={`Сигнали: ${openAlerts.length} отворени`} onClick={()=>go('alerts')}><Bell size={19}/>{openAlerts.length>0&&<i/>}</button><button className="small-avatar" aria-label="Профил и достъп" onClick={()=>session.actualRole==='admin'?openForm({type:'role'}):go('users')}>{session.role==='admin'?'АД':'РГ'}</button></div></header>
 <main id="main" className="main-content"><div className="context-line"><span><span className="live-dot"/> Симулация на телеметрия · <button onClick={()=>go('documents')}>за уточняване на изискванията</button></span><span>{fmt.format(new Date(data.serverTime))}</span></div>{error&&<div className="notice error"><TriangleAlert size={18}/><span>Опресняването не успя: {error} Показани са последните получени данни.</span><button onClick={()=>refresh()}>Повтори</button></div>}
 {(page==='overview'||page==='map')&&<><SectionHead eyebrow={page==='overview'?'ВСЯКА РЕКА. ЕДИН ПОГЛЕД.':'НАЦИОНАЛНА МРЕЖА'} title={page==='overview'?'Преглед на мрежата':'Карта на станциите'} description={page==='overview'?'Актуално състояние на станциите и речните нива в България.':'Увеличете картата, изберете пункт и проследете неговите измервания.'} actions={<><div className="refresh-control"><span className="live-dot"/><span>{auto?`Обновяване след ${countdown} s`:'Обновяването е спряно'}</span><button className="icon-button" aria-label={auto?'Спри автоматичното обновяване':'Включи автоматично обновяване'} onClick={()=>setAuto(!auto)}>{auto?<Pause size={14}/>:<Play size={14}/>}</button></div><button className="button secondary" onClick={()=>refresh()} disabled={busy}><RefreshCw size={15} className={busy?'spin':''}/>Обнови</button></>}/>
 {page==='overview'&&<div className="stats-grid"><div className="stat-card"><div className="stat-label"><span>Станции в мрежата</span><RadioTower size={18}/></div><div className="stat-value">{data.stations.length}<span className="subtle-tag">{new Set(data.stations.map(s=>s.oblast)).size} области</span></div><div className="stat-foot"><span>{tryavnaStationCount} {tryavnaStationCount===1?'пункт':'пункта'} в пилот „Трявна“</span><div className="mini-bars">{[12,19,15,23,19,26,22,30].map((h,i)=><i key={i} style={{height:h}}/>)}</div></div></div><div className="stat-card"><div className="stat-label"><span>Активни станции</span><Activity size={18}/></div><div className="stat-value">{data.stations.filter(s=>s.health==='online').length}<span className="positive-text">в мрежата</span></div><div className="stat-foot"><span><i className="dot normal"/>Редовно получаване на данни</span><Spark values={[1,1.1,1.08,1.15,1.12,1.2,1.2,1.3]}/></div></div><div className="stat-card"><div className="stat-label"><span>Активни сигнали</span><Bell size={18}/></div><div className="stat-value">{openAlerts.length}<span className="warning-text">изискват преглед</span></div><div className="stat-foot"><span><i className="dot critical"/>{openAlerts.filter(a=>a.severity==='critical').length} с критично учебно ниво</span><ArrowUpRight size={19}/></div></div><div className="stat-card"><div className="stat-label"><span>Обхванати басейни</span><Waves size={18}/></div><div className="stat-value">{new Set(data.stations.map(s=>s.basin)).size}<span className="subtle-tag">България</span></div><div className="stat-foot"><span>{new Set(data.stations.map(s=>s.river)).size} реки · {municipalities.length} общини</span><span className="basin-symbol">≈</span></div></div></div>}
 {page==='map'&&<div className="filter-toolbar"><span className="filter-label"><SlidersHorizontal size={16}/>Филтри</span><select aria-label="Община на картата" value={scope} onChange={e=>setScope(e.target.value)}><option value="">Всички общини</option>{municipalities.map(x=><option key={x}>{x}</option>)}</select><select aria-label="Състояние на картата" value={mapStatus} onChange={e=>setMapStatus(e.target.value)}><option value="">Всички състояния</option>{Object.entries(statusLabels).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select><button className="text-button" onClick={()=>{setMapStatus('');setScope('')}}>Изчисти</button></div>}
 <div className="map-layout">{mapView}{stationPanel}</div>
 {page==='overview'&&<div className="overview-bottom"><div className="card"><div className="card-header"><div className="heading-with-icon"><Bell size={17}/><h2>Изискват внимание</h2></div><button className="text-button" onClick={()=>go('alerts')}>Всички сигнали <ArrowRight size={14}/></button></div>{openAlerts.length?openAlerts.slice(0,3).map(a=>{const s=data.stations.find(s=>s.id===a.stationId);return <button className="alert-preview" key={a.id} onClick={()=>{setSelected(a.stationId);go('alerts')}}><span className={`alert-icon ${a.severity}`}>{a.severity==='offline'?<WifiOff size={18}/>:<TriangleAlert size={18}/>}</span><span><strong>{a.title}</strong><small>{s?.name} · {timeOnly(a.createdAt)}</small></span><ChevronRight size={16}/></button>}):<Empty title="Няма необработени сигнали"/>}</div><div className="pilot-callout"><div className="eyebrow">ПИЛОТНА КОНФИГУРАЦИЯ</div><span className="pilot-outline"><Mountain size={78} strokeWidth={1}/><Waves size={44} strokeWidth={1}/></span><h2>Започваме от Трявна.</h2><p>{tryavnaStationCount} {tryavnaStationCount===1?'речен пункт':'речни пункта'}. Независими измервания на нивото. Една обща картина.</p><button className="button light" onClick={()=>go('pilot')}>Разгледай пилота <ArrowUpRight size={16}/></button><small>Предложение за експертна оценка и общинско съгласуване</small></div></div>}
 </>}
 {page==='measurements'&&<Measurements data={data} selected={selected} onSelect={setSelected} notify={notify} onHandover={()=>openForm({type:'handover'})}/>}
 {page==='stations'&&<><SectionHead eyebrow="РЕГИСТЪР НА ИНФРАСТРУКТУРАТА" title="Станции" description="Датчици, речни участъци, измервателни интервали и съгласувани места за монтаж." actions={<>{['admin','municipal'].includes(session.role)&&<button className="button secondary" onClick={()=>openForm({type:'approval'})}><ShieldCheck size={16}/>Ново съгласуване</button>}{session.role==='admin'&&<button className="button primary" onClick={()=>openForm({type:'newstation'})}><Plus size={17}/>Добави станция</button>}</>}/><div className="notice"><ShieldCheck size={19}/><span>Местата се предлагат след анализ от специалисти и се предоставят чрез общината. Всички начални позиции са демонстрационни; записът на съгласуване тук служи за изпитване на процеса.</span></div><div className="card"><div className="card-header"><h2>Регистър на станциите <span className="count-badge">{data.stations.length}</span></h2><div className="input-icon"><Search size={16}/><input aria-label="Търсене в регистъра" placeholder="Станция, река, община или датчик" value={stationQuery} onChange={e=>setStationQuery(e.target.value)}/></div></div><div className="table-wrap"><table><thead><tr><th>Станция / река</th><th>Община / област</th><th>Речен участък</th><th>Състояние</th><th>Интервал / оборудване</th><th>Място за монтаж</th><th>Действия</th></tr></thead><tbody>{data.stations.filter(s=>(s.name+' '+s.id+' '+s.river+' '+s.municipality+' '+(s.riverSection?.name||'')+' '+s.sensors.map(id=>productNames[id]||id).join(' ')).toLowerCase().includes(stationQuery.toLowerCase())).map(s=><tr key={s.id}><td><button className="table-title" aria-label={`Досие на ${s.id}`} onClick={()=>setProfileId(s.id)}>{s.name}</button><small>{s.id} · р. {s.river}</small></td><td>{s.municipality}<small>{s.oblast}</small></td><td><span>{s.riverSection?.name||'Участъкът още не е описан'}</span><small>{s.riverSection?.status==='verified'?'Потвърден профил':'За експертна проверка'}</small></td><td><Badge status={s.current?.status}/></td><td>{s.interval} s<small>{s.sensors.map(id=>productNames[id]?.split(' · ')[0]||id).join(' · ')}</small></td><td><Badge status={s.locationStatus==='approved'?'normal':'proposed'}>{s.locationStatus==='approved'?'Демо одобрение':s.locationStatus==='reviewed'?'Прегледано':'Предложение'}</Badge></td><td><div className="row-actions"><button className="icon-button" aria-label={`Досие за ${s.id}`} onClick={()=>setProfileId(s.id)}><BookOpen size={16}/></button><button className="icon-button" aria-label={`Карта за ${s.id}`} onClick={()=>{setSelected(s.id);go('map');setFocus({lat:s.lat,lng:s.lng,zoom:12,key:Date.now()})}}><MapPin size={16}/></button>{canManage(session,s.municipality)&&<button className="icon-button" aria-label={`Редактирай ${s.id}`} onClick={()=>openForm({type:'station',id:s.id})}><Settings2 size={16}/></button>}{canService(session,s.municipality)&&<button className="icon-button" aria-label={`Сервиз за ${s.id}`} onClick={()=>openForm({type:'ticket',stationId:s.id})}><Wrench size={16}/></button>}<button className="icon-button" aria-label={`Измервания за ${s.id}`} onClick={()=>{setSelected(s.id);go('measurements')}}><ChartNoAxesCombined size={16}/></button></div></td></tr>)}</tbody></table></div></div><div className="card spaced"><div className="card-header"><h2>Съгласуване на местоположения</h2><span className="muted">Експерт → община → приложим режим → монтаж</span></div>{data.approvals.length?<div className="table-wrap"><table><thead><tr><th>Пункт</th><th>Експерт / община</th><th>Режим / документ</th><th>Статус</th><th>Действия</th></tr></thead><tbody>{data.approvals.map(a=><tr key={a.id}><td>{a.stationId}<small>{a.id}</small></td><td>{a.expert}<small>{a.municipalReference}</small></td><td>{a.regime}<small>{a.documentReference}</small></td><td><Badge status={a.status==='approved'?'normal':'proposed'}>{a.status==='approved'?'Одобрено в демо':a.status==='rejected'?'Върнато':'За преглед'}</Badge></td><td>{a.status!=='approved'&&session.role==='admin'&&<button className="button small secondary" onClick={()=>mutate(`approvals/${a.id}`,{status:'approved'},'PATCH','Съгласуването е одобрено в демонстрационния процес.')}>Одобри</button>}</td></tr>)}</tbody></table></div>:<Empty title="Все още няма подадени съгласувания" description="Добавете експертно становище, общинска препратка и приложимия административен режим."/>}</div></>}
 {page==='alerts'&&<><SectionHead eyebrow="ОПЕРАТИВЕН ЦЕНТЪР" title="Сигнали и събития" description="Учебни прагове за речни нива и технически събития. Потвърждението на сигнал се записва в журнала." actions={<button className="button secondary" onClick={()=>openForm({type:'handover'})}><Send size={16}/>Подготви предаване</button>}/><div className="tabs"><button className={alertTab==='open'?'active':''} onClick={()=>setAlertTab('open')}>Необработени <span>{openAlerts.length}</span></button><button className={alertTab==='acknowledged'?'active':''} onClick={()=>setAlertTab('acknowledged')}>Потвърдени</button><button className={alertTab==='all'?'active':''} onClick={()=>setAlertTab('all')}>Всички</button></div><div className="alert-list">{data.alerts.filter(a=>alertTab==='all'||a.status===alertTab).map(a=>{const s=data.stations.find(s=>s.id===a.stationId);return <div className={`card incident-card ${a.severity}`} key={a.id}><div className={`alert-icon ${a.severity}`}>{a.severity==='offline'?<WifiOff size={22}/>:<TriangleAlert size={22}/>}</div><div className="incident-main"><div className="inline-row"><h3>{a.title}</h3><Badge status={a.severity}/></div><p>{s?.name} · {s?.river} · {a.stationId}</p><div className="incident-meta"><span><Clock size={13}/>{dateTime(a.createdAt)}</span><span>{a.status==='acknowledged'?`Потвърден от ${a.ackBy||'оператор'}`:'Очаква преглед от отговорния оператор'}</span></div>{a.note&&<p className="incident-note">{a.note}</p>}</div><div className="incident-actions"><button className="button secondary small" onClick={()=>{setSelected(a.stationId);go('map')}}>Към станцията</button>{a.status==='open'&&canManage(session,s?.municipality||'')&&<button className="button primary small" onClick={()=>openForm({type:'ack',id:a.id})}><CheckCheck size={15}/>Потвърди</button>}</div></div>})}{!data.alerts.filter(a=>alertTab==='all'||a.status===alertTab).length&&<Empty title="Няма сигнали в този изглед" description="Новите събития ще се появят при следващото обновяване."/>}</div><div className="notice"><Bell size={18}/><span>Това е вътрешен регистър на демонстрационни събития. Официалното оповестяване и действията при бедствие се извършват по утвърдените планове и компетентности.</span></div></>}
 {(page==='pilot'||page==='equipment')&&<Equipment section={page} stations={data.stations} orders={data.orders} session={session} onOrder={id=>openForm({type:'order',productId:id})} notify={notify}/>}
 {page==='orders'&&<><SectionHead eyebrow="ДОСТАВКИ И ОБОРУДВАНЕ" title="Заявки за доставка" description="Проследете необходимото оборудване от заявяване до вътрешно одобрение и приемане." actions={['admin','municipal'].includes(session.role)&&<button className="button primary" onClick={()=>openForm({type:'order'})}><Plus size={17}/>Нова заявка</button>}/><div className="process-strip">{['1. Заявяване','2. Преглед','3. Одобрение','4. Договор и доставка','5. Приемане'].map((x,i)=><span key={x}><i>{i+1}</i>{x.substring(3)}{i<4&&<ChevronRight size={15}/>}</span>)}</div><div className="notice"><ShoppingCart size={18}/><span>Вътрешните заявки са демонстрационни и не се изпращат към доставчик. Офертата, приложимият ред за възлагане, договорът, гаранциите и цените се потвърждават отделно.</span></div><div className="card"><div className="card-header"><h2>Регистър на заявките</h2><button className="text-button" onClick={()=>go('equipment')}>Към каталога <ArrowUpRight size={15}/></button></div>{data.orders.length?<div className="table-wrap"><table><thead><tr><th>Заявка / оборудване</th><th>Община</th><th>Количество</th><th>Статус</th><th>Дата</th><th>Действия</th></tr></thead><tbody>{data.orders.map(o=><tr key={o.id}><td><strong>{productNames[o.productId]||o.productId}</strong><small>{o.id} · {o.reason}</small></td><td>{o.municipality}</td><td>{o.quantity} бр.</td><td><Badge status={o.status==='approved'||o.status==='received'?'normal':o.status==='rejected'?'critical':'proposed'}>{{draft:'Чернова',submitted:'За одобрение',approved:'Одобрена',rejected:'Отказана',received:'Приета'}[o.status]}</Badge></td><td>{dateTime(o.createdAt)}</td><td>{session.role==='admin'&&<div className="row-actions">{o.status==='submitted'&&<><button className="button small secondary" onClick={()=>mutate(`orders/${o.id}`,{status:'approved'},'PATCH')}>Одобри</button><button className="text-button danger-text" onClick={()=>mutate(`orders/${o.id}`,{status:'rejected',note:'Отказана в демонстрационния процес.'},'PATCH')}>Откажи</button></>}{o.status==='approved'&&<button className="button small secondary" onClick={()=>mutate(`orders/${o.id}`,{status:'received',note:'Демонстрационно приемане.'},'PATCH')}>Демо приемане</button>}</div>}</td></tr>)}</tbody></table></div>:<Empty title="Подгответе първата заявка" description="Изберете оборудване от каталога, количество и общината, за която е необходимо."/>}</div></>}
 {page==='service'&&<><SectionHead eyebrow="НАДЕЖДНОСТ НА МРЕЖАТА" title="Сервиз и поддръжка" description="Технически проблеми, планови проверки, ремонт и проследяване на гаранционен случай." actions={technicalStations.length>0&&<button className="button primary" onClick={()=>openForm({type:'ticket'})}><Plus size={17}/>Нова сервизна заявка</button>}/><div className="service-metrics"><div className="card"><Wrench size={21}/><strong>{data.tickets.filter(t=>t.status==='open').length}</strong><span>Отворени заявки</span></div><div className="card"><Clock size={21}/><strong>{data.tickets.filter(t=>t.status==='in_progress').length}</strong><span>В процес на обработка</span></div><div className="card"><CheckCircle2 size={21}/><strong>{data.tickets.filter(t=>t.status==='resolved').length}</strong><span>Приключени случаи</span></div></div><div className="card"><div className="card-header"><h2>Сервизен регистър</h2><button className="text-button" onClick={()=>go('documents')}>Работни протоколи <ArrowRight size={15}/></button></div>{data.tickets.length?data.tickets.map(t=>{const s=data.stations.find(s=>s.id===t.stationId);return <div className="service-row" key={t.id}><div className="service-row-icon"><Wrench size={19}/></div><div><h3>{t.subject}</h3><p>{t.description}</p><small>{s?.name} · {t.id} · {dateTime(t.createdAt)}</small>{t.resolution&&<p className="resolution"><CheckCircle2 size={14}/>{t.resolution}</p>}</div><div className="service-status"><Badge status={t.status==='resolved'?'normal':t.priority==='critical'?'critical':'warning'}>{{open:'Нова',in_progress:'В обработка',resolved:'Приключена'}[t.status]}</Badge>{canService(session,s?.municipality||'')&&t.status!=='resolved'&&(t.status==='open'?<button className="button small secondary" onClick={()=>mutate(`tickets/${t.id}`,{status:'in_progress'},'PATCH')}>Поеми случая</button>:<button className="button small secondary" onClick={()=>openForm({type:'resolve',id:t.id})}>Приключи</button>)}</div></div>}):<Empty title="Няма регистрирани сервизни заявки" description="Използвайте регистъра за повреда, проверка, калибриране или гаранционен случай."/>}</div><div className="content-grid spaced"><div className="card card-body"><h3>При повреда на хардуера</h3><ol className="numbered-list"><li>Обезопасете работата и отбележете качеството на данните.</li><li>Регистрирайте модел, сериен номер, симптоми, време и снимков материал.</li><li>Проверете договора и гаранционния срок на конкретната доставка.</li><li>Получете RMA / сервизен номер и указания от доставчика.</li><li>След ремонта проведете сравнение с контролно измерване и приемане.</li></ol></div><div className="card card-body"><h3>Препоръчителна планова проверка</h3><p className="muted">Проектен график; окончателно се определя по инструкциите на производителя и местните рискове.</p><ul className="checklist"><li>Дистанционен контрол на батерия и връзка — ежедневно.</li><li>Оглед и почистване — ежемесечно и след високи води.</li><li>Проверка на условната нула, монтаж и рейка — след намеса.</li><li>Калибриране — по спецификация и сервизна програма.</li></ul></div></div></>}
 {['documents','training','compliance','quality'].includes(page)&&<Knowledge section={page as 'documents'|'training'|'compliance'|'quality'} completed={data.trainingCompletions} onComplete={async(id:string)=>{if(!await mutate(`trainings/${id}/complete`,{},'POST','Обучението е отбелязано като преминато.'))throw new Error('Записът не успя.')}} notify={notify}/>}
 {page==='automation'&&<><SectionHead eyebrow="ПРАВИЛА НА СИСТЕМАТА" title="Автоматизации" description="Сървърни проверки на входящите данни, учебните прагове и състоянието на станциите."/><div className="notice"><Workflow size={19}/><span>Демонстрационните правила се оценяват при опресняване и приемане на телеметрия. Независимата работа при затворен браузър изисква реален поток от устройства или планирано извикване на услугата.</span></div><div className="automation-grid">{data.rules.map(r=><div className="card automation-card" key={r.id}><div className="automation-top"><span className="feature-icon"><Workflow size={22}/></span><button className={`toggle ${r.enabled?'on':''}`} role="switch" aria-checked={r.enabled} aria-label={`Правило ${r.name}`} disabled={session.role!=='admin'||busy} onClick={()=>mutate(`rules/${r.id}`,{enabled:!r.enabled},'PATCH')}><span/></button></div><h3>{r.name}</h3><p>{r.description}</p><div className="automation-foot"><Badge status={r.enabled?'normal':'offline'}>{r.enabled?'Включено':'Изключено'}</Badge><span>Проверка през {r.interval} s</span></div><small className="muted">Последно изпълнение: {dateTime(r.lastRun||undefined)}</small></div>)}</div><div className="card spaced"><div className="card-header"><h2>Интеграция на устройства</h2><Badge status="proposed">Подготвен интерфейс</Badge></div><div className="card-body prose"><p>Устройствата подават измервания към <code>POST /api/ingest</code> с удостоверяване. Когато служебният ключ не е конфигуриран, приемането е изключено. Реалният интерфейс не използва демонстрационните профили.</p><p>Проверките обхващат стойности, единици, идентификатор на станцията, време на измерване, повторни пакети и валидност на ключа. Суровите данни се пазят отделно от операторските оценки.</p><div className="notice compact"><Shield size={17}/><span>Ключовете се конфигурират на сървъра и не се показват в приложението. За внедряване са необходими отделни удостоверения за устройствата и договорен режим за ротация.</span></div></div></div></>}
 {page==='users'&&<><SectionHead eyebrow="ПРАВА И ОТГОВОРНОСТИ" title="Достъп и роли" description="Проверете как системата се държи за различните участници и общински обхвати." actions={<>{session.actualRole==='admin'&&<button className="button secondary" onClick={()=>openForm({type:'role'})}><Eye size={16}/>Изпробвай роля</button>}{session.role==='admin'&&<button className="button primary" onClick={()=>openForm({type:'member'})}><Plus size={16}/>Добави потребител</button>}</>}/><div className="profile-banner"><span className="avatar large">{session.role==='admin'?'АД':'РГ'}</span><div><h2>{roleLabels[session.role]}</h2><p>{session.municipality?`Обхват: община ${session.municipality}`:'Обхват: национална мрежа'} · {session.demo?'Демонстрационен профил':'Основен профил'}</p></div><Badge status="normal">Сървърна проверка на правата</Badge></div><div className="card"><div className="card-header"><h2>Матрица на достъпа</h2></div><div className="table-wrap"><table className="permissions-table"><thead><tr><th>Действие</th>{Object.values(roleLabels).map(r=><th key={r}>{r}</th>)}</tr></thead><tbody>{permissions.map(row=><tr key={row[0]}>{row.map((v,i)=><td key={i} className={v==='—'?'muted':''}>{v}</td>)}</tr>)}</tbody></table></div></div><div className="card spaced"><div className="card-header"><h2>Регистрирани профили</h2></div><div className="table-wrap"><table><thead><tr><th>Потребител</th><th>Роля</th><th>Община</th></tr></thead><tbody>{data.memberships.map(m=><tr key={m.userId}><td><strong>{m.name}</strong><small>{m.userId}</small></td><td>{roleLabels[m.role]}</td><td>{m.municipality||'Национален обхват'}</td></tr>)}</tbody></table></div></div><div className="notice spaced"><ShieldCheck size={18}/><span>Само действителният администратор може да превключва демонстрационните профили. Достъпът до частния сайт и приложните роли се управляват отделно; добавянето на роля не изпраща покана.</span></div></>}
 {page==='audit'&&<><SectionHead eyebrow="ПРОСЛЕДИМОСТ" title="Журнал на действията" description="Сървърен запис на промените, експортите, съгласуванията и потвърдените събития."/><div className="card"><div className="card-header"><h2>Последни действия</h2><div className="input-icon"><Search size={16}/><input aria-label="Търси в журнала" placeholder="Потребител, действие, обект" value={auditQuery} onChange={e=>setAuditQuery(e.target.value)}/></div></div><div className="table-wrap"><table><thead><tr><th>Дата и час</th><th>Участник / роля</th><th>Действие</th><th>Обект</th><th>Подробности</th></tr></thead><tbody>{data.audit.filter(a=>(a.actor+a.action+a.entity+a.details).toLowerCase().includes(auditQuery.toLowerCase())).map(a=><tr key={a.id}><td className="nowrap">{dateTime(a.createdAt)}</td><td>{a.actor}<small>{roleLabels[a.role]}</small></td><td><span className="audit-action">{a.action}</span></td><td className="code">{a.entity}</td><td className="audit-details">{a.details}</td></tr>)}</tbody></table></div>{!data.audit.length&&<Empty title="Журналът е готов за първото действие"/>}</div></>}
 <footer className="app-footer"><span><Waves size={15}/>RiverGuard България <span className="footer-dot">·</span> Учебна система за уточняване на изискванията</span><span>Часова зона: Europe/Sofia <span className="footer-dot">·</span><button onClick={()=>go('compliance')}>Източници и правила</button></span></footer>
 </main></div>
 {toast&&<div className="toast" role="status"><CheckCircle2 size={18}/><span>{toast}</span><button aria-label="Затвори известието" onClick={()=>setToast('')}><X size={16}/></button></div>}
 {profileStation&&<Modal title={`Досие · ${profileStation.name}`} onClose={()=>setProfileId(null)} wide>
  <Field label="Избери станция за преглед"><select value={profileStation.id} onChange={e=>setProfileId(e.target.value)}>{data.stations.map(s=><option value={s.id} key={s.id}>{s.id} · {s.name}</option>)}</select></Field>
  <StationProfile station={profileStation} onEdit={canManage(session,profileStation.municipality)?()=>{setProfileId(null);openForm({type:'station',id:profileStation.id})}:undefined} onEquipment={()=>{setProfileId(null);go('equipment')}}/>
 </Modal>}
 {form&&<Modal title={{role:'Изпробвай демонстрационен профил',order:'Нова заявка за оборудване',station:'Настройки на станцията',newstation:'Добавяне на демонстрационна станция',ticket:'Нова сервизна заявка',resolve:'Приключване на сервизен случай',ack:'Потвърждаване на сигнал',approval:'Съгласуване на място за монтаж',member:'Добавяне на приложна роля',handover:'Протокол за предаване на данни'}[form.type]||'Нова операция'} onClose={()=>setForm(null)} wide={['station','newstation','approval'].includes(form.type)}><form ref={formRef} onSubmit={submit}>
 {form.type==='role'&&<><p className="form-intro">Превключването служи за проверка на сценариите. Правата на избрания профил се прилагат на сървъра.</p><Field label="Роля"><select name="role" defaultValue={session.role}>{Object.entries(roleLabels).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></Field><Field label="Община" hint="Използва се за общински оператор и сервизен техник."><select name="municipality" defaultValue={session.municipality||'Трявна'}>{municipalities.map(m=><option key={m}>{m}</option>)}</select></Field></>}
 {form.type==='order'&&<><div className="notice compact">Демонстрационна вътрешна заявка. Не води до покупка или изпращане към доставчик.</div><Field label="Оборудване"><select name="productId" defaultValue={form.productId||'rls500'}>{Object.entries(productNames).map(([id,n])=><option key={id} value={id}>{n}</option>)}</select></Field><div className="form-grid"><Field label="Община"><select name="municipality" defaultValue={session.municipality||'Трявна'}>{(session.role==='admin'?municipalities:[session.municipality||'']).map(m=><option key={m}>{m}</option>)}</select></Field><Field label="Количество"><input type="number" name="quantity" min="1" max="1000" required defaultValue="1"/></Field></div><Field label="Обосновка / предназначение"><textarea name="reason" required minLength={5} maxLength={2000} placeholder="Напр. независим контрол на нивото за пункт TRV-002…" rows={3}/></Field></>}
 {(form.type==='station'||form.type==='newstation')&&<><div className="notice compact">Праговете са учебни, а координатите — предложение. Одобряването на място се извършва през отделния процес на съгласуване.</div><div className="form-grid"><Field label="Идентификатор"><input name="id" required defaultValue={activeFormStation?.id||''} readOnly={form.type==='station'} pattern="[A-Z0-9-]{3,30}" placeholder="TRV-006"/></Field><Field label="Наименование"><input name="name" required defaultValue={activeFormStation?.name||''}/></Field><Field label="Река"><input name="river" required defaultValue={activeFormStation?.river||'Тревненска'}/></Field><Field label="Община"><input name="municipality" required defaultValue={activeFormStation?.municipality||session.municipality||'Трявна'} readOnly={session.role!=='admin'}/></Field><Field label="Област"><input name="oblast" required defaultValue={activeFormStation?.oblast||'Габрово'}/></Field><Field label="Регион"><select name="region" defaultValue={activeFormStation?.region||'Северен централен'}>{['Северозападен','Северен централен','Североизточен','Югозападен','Южен централен','Югоизточен'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Басейнов район"><select name="basin" defaultValue={activeFormStation?.basin||'Дунавски'}>{['Дунавски','Черноморски','Източнобеломорски','Западнобеломорски'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Състояние"><select name="health" defaultValue={activeFormStation?.health||'online'}><option value="online">Онлайн · симулация</option><option value="offline">Без връзка · симулация</option><option value="maintenance">В поддръжка</option></select></Field><Field label="Географска ширина"><input name="lat" type="number" step=".000001" min="41" max="44.5" defaultValue={activeFormStation?.lat||42.875} required/></Field><Field label="Географска дължина"><input name="lng" type="number" step=".000001" min="22" max="29" defaultValue={activeFormStation?.lng||25.493} required/></Field><Field label="Интервал · секунди"><select name="interval" defaultValue={activeFormStation?.interval||60}>{[30,60,120,300,600].map(x=><option key={x} value={x}>{x} s</option>)}</select></Field><Field label="Учебен праг „Внимание“ · m"><input name="warning" type="number" step=".01" min="0" max="30" defaultValue={activeFormStation?.warning||1.8} required/></Field><Field label="Учебен критичен праг · m"><input name="critical" type="number" step=".01" min="0" max="30" defaultValue={activeFormStation?.critical||2.35} required/></Field></div><Field label="Бележки"><textarea name="notes" rows={2} maxLength={2000} defaultValue={activeFormStation?.notes||'Предложение за експертна оценка.'}/></Field><RiverSectionFields station={activeFormStation} canVerify={session.role==='admin'}/></>}
 {form.type==='ticket'&&<><Field label="Станция"><select name="stationId" defaultValue={form.stationId||selected}>{technicalStations.map(s=><option key={s.id} value={s.id}>{s.name} · {s.id}</option>)}</select></Field><Field label="Проблем / планирана дейност"><input name="subject" required minLength={3} maxLength={160} placeholder="Напр. липса на телеметрия / проверка на датчик"/></Field><Field label="Приоритет"><select name="priority"><option value="normal">Нормален</option><option value="high">Висок</option><option value="critical">Критичен</option></select></Field><Field label="Описание"><textarea name="description" required minLength={5} maxLength={4000} rows={4} placeholder="Модел, сериен номер, симптоми, начало, извършени проверки, гаранционен документ…"/></Field></>}
 {form.type==='resolve'&&<Field label="Извършени действия и резултат от проверката"><textarea name="resolution" required minLength={5} rows={4} maxLength={3000}/></Field>}
 {form.type==='ack'&&<><p className="form-intro">Потвърждавате, че сигналът е прегледан. Това не означава, че причината е отстранена или че е издадено официално предупреждение.</p><Field label="Бележка / предприети действия"><textarea name="note" required minLength={3} maxLength={2000} rows={4}/></Field></>}
 {form.type==='approval'&&<><div className="notice compact">Работна демонстрация на процеса. Не замества действителното становище или разрешение от компетентния орган.</div><Field label="Станция"><select name="stationId" defaultValue={form.stationId||selected}>{editableStations.map(s=><option value={s.id} key={s.id}>{s.name} · {s.id}</option>)}</select></Field><div className="form-grid"><Field label="Експерт / становище"><input name="expert" required maxLength={200} placeholder="Име / организация / № на становище"/></Field><Field label="Общинска препратка"><input name="municipalReference" required maxLength={200} placeholder="Решение / входящ номер"/></Field><Field label="Определен административен режим"><select name="regime" required><option value="">Изберете след експертна оценка</option><option>Разрешително за ползване на воден обект</option><option>Уведомяване по чл. 58 ЗВ · одобрена програма</option><option>Друг приложим режим · по становище</option></select></Field><Field label="Документ / регистрова препратка"><input name="documentReference" required maxLength={250} placeholder="Номер и орган / препратка към досие"/></Field></div><Field label="Обосновка и условия за монтаж"><textarea name="notes" required rows={3} maxLength={2000}/></Field></>}
 {form.type==='member'&&<><div className="notice compact">Използвайте проверения идентификатор на потребителя за този сайт. Добавянето не променя аудиторията на частния сайт и не изпраща покана.</div><Field label="Идентификатор на потребителя"><input name="userId" required maxLength={160}/></Field><Field label="Име за показване"><input name="name" required maxLength={160}/></Field><div className="form-grid"><Field label="Роля"><select name="role">{Object.entries(roleLabels).map(([k,v])=><option value={k} key={k}>{v}</option>)}</select></Field><Field label="Община за ограничените роли"><select name="municipality"><option value="">Национален обхват</option>{municipalities.map(m=><option key={m}>{m}</option>)}</select></Field></div></>}
 {form.type==='handover'&&<><p className="form-intro">Подгответе файл за разпечатване и попълване. Данните не се изпращат автоматично на други лица.</p><Field label="Станция"><select name="stationId" defaultValue={selected}>{data.stations.filter(s=>session.role!=='municipal'||s.municipality===session.municipality).map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></Field><Field label="Получател / компетентна институция"><input name="recipient" required placeholder="Напр. отговорно звено в общината" maxLength={250}/></Field><Field label="Основание и цел"><textarea name="purpose" required rows={2} maxLength={1000}/></Field><Field label="Наименования на приложените файлове"><input name="files" placeholder="RiverGuard_measurements.csv…" required maxLength={500}/></Field></>}
 {formError&&<div className="notice error" role="alert">{formError}</div>}<div className="form-actions"><button type="button" className="button secondary" onClick={()=>setForm(null)}>Отказ</button><button className="button primary" type="submit" disabled={busy}>{busy?<LoaderCircle className="spin" size={16}/>:form.type==='handover'?<Download size={16}/>:<Check size={16}/>} {form.type==='handover'?'Изтегли протокола':form.type==='role'?'Приложи профила':form.type==='order'?'Подай заявката':'Запази'}</button></div>
 </form></Modal>}
 </div>;
}
function escapeHtml(s:string){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]||c))}
